class Solution {public long solve(int[] a,int[] b){if(a.length>b.length){int[] t=a;a=b;b=t;}int n=a.length+b.length,half=(n+1)/2,l=0,h=a.length;while(l<=h){int i=l+(h-l)/2,j=half-i;long x=i>0?a[i-1]:Long.MIN_VALUE,y=i<a.length?a[i]:Long.MAX_VALUE,u=j>0?b[j-1]:Long.MIN_VALUE,v=j<b.length?b[j]:Long.MAX_VALUE;if(x<=v&&u<=y)return n%2==1?2*Math.max(x,u):Math.max(x,u)+Math.min(y,v);if(x>v)h=i-1;else l=i+1;}throw new IllegalArgumentException();}}